class Solution:
    def twoSum(self, nums, targetIdx) -> list[list[int]]:
        target = -nums[targetIdx]
        l, r = targetIdx + 1, len(nums) - 1
        triplets = []

        while l < r:
            total = nums[l] + nums[r]
            if total == target:
                triplets.append([nums[targetIdx], nums[l], nums[r]])
                l += 1
                r -= 1

                while l < r and nums[l] == nums[l - 1]:
                    l += 1

            elif total > target:
                r -= 1
            else:
                l += 1

        return triplets

    def threeSum(self, nums: list[int]) -> list[list[int]]:
        nums.sort()
        ans = []

        for i in range(len(nums)):
            if nums[i] > 0:
                break
            if i == 0 or nums[i] != nums[i - 1]:
                ans += self.twoSum(nums, i)

        return ans
